/**
 * Minimal, dependency-free replacement for the `jwt-decode` package.
 *
 * Decodes a JWT *without* verifying its signature - it merely base64url-decodes
 * and JSON-parses the requested part (payload by default, header on demand).
 * Signature verification happens elsewhere (see Jwk#verify).
 *
 * The public API mirrors jwt-decode (`jwtDecode(token, { header })` +
 * `InvalidTokenError`) so it can be used as a drop-in replacement.
 */

class InvalidTokenError extends Error {}
InvalidTokenError.prototype.name = "InvalidTokenError";

/**
 * Decodes a single JWT part (base64url -> UTF-8 -> JSON).
 * @param {string} part
 * @param {number} index - 0-based part index, only used for error messages
 * @returns {object}
 */
function decodePart(part, index) {
    if (typeof part !== "string") {
        throw new InvalidTokenError(`Invalid token specified: missing part #${index + 1}`);
    }

    let decoded;
    try {
        decoded = Buffer.from(part, "base64url").toString("utf8");
    } catch (e) {
        throw new InvalidTokenError(`Invalid token specified: invalid base64 for part #${index + 1} (${e.message})`);
    }

    try {
        return JSON.parse(decoded);
    } catch (e) {
        throw new InvalidTokenError(`Invalid token specified: invalid json for part #${index + 1} (${e.message})`);
    }
}

/**
 * Decodes the payload (or, with `{ header: true }`, the header) of a JWT.
 * @param {string} token - the raw JWT
 * @param {object} [options]
 * @param {boolean} [options.header=false] - decode the header instead of the payload
 * @returns {object} the decoded header or payload
 * @throws {InvalidTokenError} if the token is not a decodable JWT
 */
function jwtDecode(token, options = {}) {
    if (typeof token !== "string") {
        throw new InvalidTokenError("Invalid token specified: must be a string");
    }

    const pos = options.header === true ? 0 : 1;
    return decodePart(token.split(".")[pos], pos);
}

module.exports = { jwtDecode, InvalidTokenError };
